export const interviewById = new Map(INTERVIEW.map(q => [q.id, q]))

export interface AnswerReview { covered: string[]; missing: string[]; score: number }

/**
 * Local, offline self-check: matches key points by keywords. It is a study aid —
 * it cannot judge correctness the way a person (or an AI reviewer) could.
 */
export function reviewAnswer(q: InterviewQuestion, answer: string): AnswerReview {
  const a = answer.toLowerCase()
  const covered: string[] = []; const missing: string[] = []
  for (const pt of q.points) (pt.keywords.some(k => a.includes(k.toLowerCase())) ? covered : missing).push(pt.text)
  return { covered, missing, score: Math.round((covered.length / q.points.length) * 100) }
}
